<?php

declare(strict_types=1);

namespace BrotherTours\OperationsApi\Tours;

use BrotherTours\OperationsApi\Auth\Csrf;
use WP_Query;
use WP_REST_Request;

use function BrotherTours\OperationsApi\error;
use function BrotherTours\OperationsApi\response;

final class DeparturesController {
	public function register():void{add_action('rest_api_init',array($this,'routes'));}
	public function routes():void{
		register_rest_route(BTOA_NAMESPACE,'/departures',array(array('methods'=>'GET','callback'=>array($this,'list'),'permission_callback'=>static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',false)),array('methods'=>'POST','callback'=>array($this,'create'),'permission_callback'=>static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',true))));
		register_rest_route(BTOA_NAMESPACE,'/departures/(?P<id>\d+)',array(array('methods'=>'GET','callback'=>array($this,'get'),'permission_callback'=>static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',false)),array('methods'=>'PATCH','callback'=>array($this,'update'),'permission_callback'=>static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',true)),array('methods'=>'DELETE','callback'=>array($this,'delete'),'permission_callback'=>static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',true))));
	}
	public function list(WP_REST_Request $r){$page=max(1,(int)$r->get_param('page'));$per=min(100,max(1,(int)($r->get_param('per_page')?:50)));$meta_query=array('relation'=>'AND');$tour=absint($r->get_param('tour_id'));if($tour)$meta_query[]=array('key'=>'wpistic_dep_tour','value'=>$tour,'compare'=>'=');$from=$this->date((string)$r->get_param('from'));if($from)$meta_query[]=array('key'=>'wpistic_dep_date','value'=>$from,'compare'=>'>=','type'=>'DATE');$to=$this->date((string)$r->get_param('to'));if($to)$meta_query[]=array('key'=>'wpistic_dep_date','value'=>$to,'compare'=>'<=','type'=>'DATE');$status=sanitize_key((string)$r->get_param('status'));if(in_array($status,array('open','limited','closed'),true))$meta_query[]=array('key'=>'wpistic_dep_status','value'=>$status,'compare'=>'=');$q=new WP_Query(array('post_type'=>'wpistic_departure','post_status'=>array('publish','draft','private'),'paged'=>$page,'posts_per_page'=>$per,'meta_query'=>$meta_query,'meta_key'=>'wpistic_dep_date','orderby'=>'meta_value','order'=>'ASC'));return response(array('items'=>array_map(fn($p)=>$this->format($p->ID),$q->posts),'total'=>(int)$q->found_posts,'page'=>$page,'perPage'=>$per,'totalPages'=>(int)$q->max_num_pages));}
	public function get(WP_REST_Request $r){$id=(int)$r['id'];return $this->valid($id)?response($this->format($id)):error('bt_ops_departure_not_found',__('Departure not found.','brother-tours-operations-api'),404);}
	public function create(WP_REST_Request $r){$p=$this->params($r);$validated=$this->validate($p);if(is_wp_error($validated))return $validated;$tour=(int)$validated['tourId'];$date=(string)$validated['date'];$id=wp_insert_post(array('post_type'=>'wpistic_departure','post_title'=>sanitize_text_field((string)($p['title']??(get_the_title($tour).' — '.$date))),'post_status'=>'publish'),true);if(is_wp_error($id))return $id;$this->save((int)$id,$validated);return response($this->format((int)$id),201);}
	public function update(WP_REST_Request $r){$id=(int)$r['id'];if(!$this->valid($id))return error('bt_ops_departure_not_found',__('Departure not found.','brother-tours-operations-api'),404);if(!current_user_can('edit_post',$id))return error('bt_ops_departure_forbidden',__('You cannot edit this departure.','brother-tours-operations-api'),403);$current=array('tourId'=>(int)get_post_meta($id,'wpistic_dep_tour',true),'date'=>(string)get_post_meta($id,'wpistic_dep_date',true),'seatsTotal'=>(int)get_post_meta($id,'wpistic_dep_seats_total',true),'seatsLeft'=>(int)get_post_meta($id,'wpistic_dep_seats_left',true),'status'=>(string)get_post_meta($id,'wpistic_dep_status',true));$p=array_merge($current,$this->params($r));$validated=$this->validate($p);if(is_wp_error($validated))return $validated;if(isset($p['title']))wp_update_post(array('ID'=>$id,'post_title'=>sanitize_text_field((string)$p['title'])));$this->save($id,$validated);return response($this->format($id));}
	public function delete(WP_REST_Request $r){$id=(int)$r['id'];if(!$this->valid($id))return error('bt_ops_departure_not_found',__('Departure not found.','brother-tours-operations-api'),404);if(!current_user_can('delete_post',$id))return error('bt_ops_departure_forbidden',__('You cannot delete this departure.','brother-tours-operations-api'),403);global $wpdb;$bookings=$wpdb->prefix.'wpistic_bookings';$linked=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$bookings} WHERE departure_id=%d",$id));if($linked>0)return error('bt_ops_departure_in_use',__('This departure has linked inquiries/bookings and cannot be deleted.','brother-tours-operations-api'),409,array('linkedBookings'=>$linked));return wp_delete_post($id,true)?response(array('id'=>$id,'deleted'=>true)):error('bt_ops_departure_delete_failed',__('Delete failed.','brother-tours-operations-api'),500);}
	private function validate(array $p){$tour=absint($p['tourId']??0);if(!$tour||'wpistic_tour'!==get_post_type($tour))return error('bt_ops_departure_tour_required',__('A valid tour is required.','brother-tours-operations-api'),422);$date=$this->date((string)($p['date']??''));if(!$date)return error('bt_ops_departure_date_required',__('A valid YYYY-MM-DD departure date is required.','brother-tours-operations-api'),422);$total=max(0,(int)($p['seatsTotal']??0));$left=max(0,(int)($p['seatsLeft']??$total));if($left>$total)return error('bt_ops_departure_capacity_invalid',__('Seats left cannot exceed total seats.','brother-tours-operations-api'),422);$status=sanitize_key((string)($p['status']??'open'));if(!in_array($status,array('open','limited','closed'),true))$status='open';return array('tourId'=>$tour,'date'=>$date,'seatsTotal'=>$total,'seatsLeft'=>$left,'status'=>$status);}
	private function save(int $id,array $p):void{update_post_meta($id,'wpistic_dep_tour',(int)$p['tourId']);update_post_meta($id,'wpistic_dep_date',(string)$p['date']);update_post_meta($id,'wpistic_dep_seats_total',(int)$p['seatsTotal']);update_post_meta($id,'wpistic_dep_seats_left',(int)$p['seatsLeft']);update_post_meta($id,'wpistic_dep_status',(string)$p['status']);}
	private function format(int $id):array{$tour=(int)get_post_meta($id,'wpistic_dep_tour',true);return array('id'=>$id,'title'=>(string)get_the_title($id),'tourId'=>$tour,'tour'=>$tour?(string)get_the_title($tour):'','date'=>(string)get_post_meta($id,'wpistic_dep_date',true),'seatsTotal'=>(int)get_post_meta($id,'wpistic_dep_seats_total',true),'seatsLeft'=>(int)get_post_meta($id,'wpistic_dep_seats_left',true),'status'=>(string)get_post_meta($id,'wpistic_dep_status',true));}
	private function valid(int $id):bool{return 'wpistic_departure'===get_post_type($id);}private function params(WP_REST_Request $r):array{$j=$r->get_json_params();return is_array($j)?$j:$r->get_params();}private function date(string $v):string{$v=trim($v);return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)?$v:'';}
}
